// Walk visits all the nodes in the order they began, with how deep they are (the top level is 0). If visit returns false
// the nodes below that node are skipped.
func (t *CovenantTree) Walk(visit func(node, depth int) bool) {
	var ends []int // where the nodes we are inside of end, innermost last

	for i := 0; i < len(t.Nodes); {
		for len(ends) > 0 && ends[len(ends)-1] <= i {
			ends = ends[:len(ends)-1]
		}

		if visit(i, len(ends)) {
			ends = append(ends, i+int(t.Nodes[i].Size))
			i++
		} else {
			i += int(t.Nodes[i].Size)
		}
	}
}

// Slice is the part of the input the node matched.
func (t *CovenantTree) Slice(node int) []int {
	n := t.Nodes[node]

	return t.Input[n.Begin:n.End]
}

// Clone returns a copy of the tree that stays valid when the parser parses again.
func (t *CovenantTree) Clone() *CovenantTree {
	c := *t
	c.Nodes = append([]CovenantNode(nil), t.Nodes...)

	return &c
}

// CovenantSyntaxError says where the input went wrong and what would have been accepted there.
type CovenantSyntaxError struct {
	// Pos is the offset in the input where the parse got the farthest.
	Pos int

	// Expected are the names of what would have matched at Pos. Leaves without a name are left out.
	Expected []string

	// Found is the element at Pos, if AtEnd is false.
	Found int

	// AtEnd is true if the input ended at Pos.
	AtEnd bool
}

func (e *CovenantSyntaxError) Error() string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "syntax error at element %d", e.Pos)

	switch {
	case e.AtEnd:
		sb.WriteString(": unexpected end of input")
	default:
		fmt.Fprintf(&sb, ": unexpected %v", e.Found)
	}

	switch n := len(e.Expected); n {
	case 0:
	case 1:
		sb.WriteString(", expected " + e.Expected[0])
	default:
		sb.WriteString(", expected " + strings.Join(e.Expected[:n-1], ", ") + " or " + e.Expected[n-1])
	}

	return sb.String()
}

// CovenantErrTooDeep is returned when rules nest deeper than the limit of the parser.
var CovenantErrTooDeep = errors.New("parser: rules are nested too deeply")

// CovenantParser parses. Use one for one parse at a time; it keeps its buffers between parses, which makes the next
// parse cheaper.
type CovenantParser struct {
	in    []int
	nodes []CovenantNode

	// the farthest failure
	errPos   int
	expected []string

	silent   int
	depth    int
	maxDepth int
	tooDeep  bool
}

// NewCovenantParser creates a parser.
func NewCovenantParser() *CovenantParser {
	return &CovenantParser{maxDepth: 100000}
}

// SetMaxDepth limits how deeply rules can nest, to protect the stack.
func (p *CovenantParser) SetMaxDepth(n int) {
	p.maxDepth = n
}

// CovenantParse parses the input with a new parser.
func CovenantParse(input []int) (*CovenantTree, error) {
	return NewCovenantParser().Parse(input)
}

// Parse matches the grammar at the start of the input. The match does not have to reach the end of the input, see
// CovenantTree.End. If it does not match the error is a *CovenantSyntaxError.
func (p *CovenantParser) Parse(input []int) (*CovenantTree, error) {

	return p.parse(input)
}

func (p *CovenantParser) parse(input []int) (*CovenantTree, error) {
	if len(input) > math.MaxInt32 {
		return nil, errors.New("parser: input too long")
	}

	p.in, p.nodes, p.expected = input, p.nodes[:0], p.expected[:0]
	p.errPos, p.silent, p.depth, p.tooDeep = -1, 0, 0, false

	end := p.ruleFile(0)
	if end < 0 {
		if p.tooDeep {
			return nil, CovenantErrTooDeep
		}

		return nil, p.syntaxError()
	}

	return &CovenantTree{Input: input, Nodes: p.nodes, End: end}, nil
}

// fail notes that something named desc was expected at pos and did not match; only the farthest failure is kept.
func (p *CovenantParser) fail(pos int, desc string) {
	if p.silent > 0 {
		return
	}

	if pos > p.errPos {
		p.errPos = pos
		p.expected = p.expected[:0]
	}

	if pos == p.errPos && desc != "" {
		for _, d := range p.expected {
			if d == desc {
				return
			}
		}

		p.expected = append(p.expected, desc)
	}
}

func (p *CovenantParser) syntaxError() *CovenantSyntaxError {
	pos := max(p.errPos, 0)

	e := &CovenantSyntaxError{Pos: pos, Expected: append([]string(nil), p.expected...), AtEnd: pos >= len(p.in)}
	if !e.AtEnd {
		e.Found = p.in[pos]
	}

	return e
}

// CovenantFile is a node of the rule "file", seen through the grammar: the rules that match inside it are its methods.
type CovenantFile struct {
	Tree *CovenantTree

	// Node is the number of the node in the tree, or -1 for the top level.
	Node int
}

// AsFile is the node seen as a CovenantFile. ok is false if the node is not of that rule.
func (t *CovenantTree) AsFile(node int) (CovenantFile, bool) {
	if node < 0 || node >= len(t.Nodes) || t.Nodes[node].Rule != CovenantRuleFile {
		return CovenantFile{}, false
	}

	return CovenantFile{t, node}, true
}

// Span is where the node starts and ends in the input.
func (v CovenantFile) Span() (begin, end int) {
	return v.Tree.Span(v.Node)
}

// Slice is the part of the input the node matched.
func (v CovenantFile) Slice() []int {
	return v.Tree.Slice(v.Node)
}

// Uses are the use nodes inside, in order.
func (v CovenantFile) Uses() iter.Seq[CovenantUse] {
	return func(yield func(CovenantUse) bool) {
		for node := range v.Tree.Find(v.Node, CovenantRuleUse) {
			if !yield(CovenantUse{v.Tree, node}) {
				return
			}
		}
	}
}

// Items are the item nodes inside, in order.
func (v CovenantFile) Items() iter.Seq[CovenantItem] {
	return func(yield func(CovenantItem) bool) {
		for node := range v.Tree.Find(v.Node, CovenantRuleItem) {
			if !yield(CovenantItem{v.Tree, node}) {
				return
			}
		}
	}
}

