func (p *CovenantParser) m1(pos int) int {
	q, n := pos, 0
	for {
		mark := len(p.nodes)
		r := p.ruleUse(q)
		if r < 0 {
			p.nodes = p.nodes[:mark]
			break
		}
		n++
		if r == q {
			break
		}
		q = r
	}
	return q
}

func (p *CovenantParser) m2(pos int) int {
	q, n := pos, 0
	for {
		mark := len(p.nodes)
		r := p.ruleItem(q)
		if r < 0 {
			p.nodes = p.nodes[:mark]
			break
		}
		n++
		if r == q {
			break
		}
		q = r
	}
	return q
}

func (p *CovenantParser) m3(pos int) int {
	if pos == len(p.in) {
		return pos
	}
	p.fail(pos, "end of input")
	return -1
}

func (p *CovenantParser) m4(pos int) int {
	q := pos
	if q = p.m1(q); q < 0 {
		return -1
	}
	if q = p.m2(q); q < 0 {
		return -1
	}
	if q = p.m3(q); q < 0 {
		return -1
	}
	return q
}

func (p *CovenantParser) ruleFile(pos int) int {
	if p.depth >= p.maxDepth {
		p.tooDeep = true
		return -1
	}
	p.depth++
	i := len(p.nodes)
	p.nodes = append(p.nodes, CovenantNode{Rule: CovenantRuleFile, Begin: int32(pos)})
	end := p.m4(pos)
	p.depth--
	if end < 0 {
		p.nodes = p.nodes[:i]
		return -1
	}
	p.nodes[i].End = int32(end)
	p.nodes[i].Size = int32(len(p.nodes) - i)
	return end
}

